entries[42184] = { ["name"] = "Muster: Eisige Tasche", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schneiderei (445)\nBenötigt Die Söhne Hodirs\n- Ehrfürchtig\nBenutzen: Lehrt Euch, wie man eine eisige Tasche näht.\nDas Nähen einer eisigen Tasche ist so schwierig, dass sich ein Schneider nur alle 7 Tage daran versuchen sollte.\nVerkaufspreis:\nEisige Tasche\nWird beim Anlegen gebunden\n22 Platz Behälter\nVerkaufspreis:\nBenötigt Mondgespinst (4), Schwarztuch (4), Eterniumfaden" }
