entries[42396] = { ["name"] = "Glyphe 'Kreis der Heilung'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Kreis der Heilung' heilt 1 zusätzliches Ziel, seine Manakosten werden jedoch um 35% erhöht.\nVerkaufspreis:" }
entries[42397] = { ["name"] = "Glyphe 'Läutern'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Läutern' heilt Euer Ziel zusätzlich um 5% seiner maximalen Gesundheit, wenn erfolgreich ein schädlicher Magieeffekt oder eine Krankheit gebannt wurde.\nVerkaufspreis:" }
entries[42398] = { ["name"] = "Glyphe 'Schleier'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Verblassen' verringert nun zusätzlich Euren gesamten erlittenen Schaden um 10%.\nVerkaufspreis:" }
entries[42399] = { ["name"] = "Glyphe 'Furchtzauberschutz'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit von 'Furchtzauberschutz' um 60 Sek.\nVerkaufspreis:" }
entries[42400] = { ["name"] = "Glyphe 'Inneres Sanktum'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Euer Zauber 'Inneres Feuer' aktiv ist, wird zusätzlich Euer erlittener Zauberschaden um 6% verringert. Zudem wird der Bewegungstempobonus Eures Zaubers 'Innerer Wille' um 6% erhöht.\nVerkaufspreis:" }
entries[42401] = { ["name"] = "Glyphe 'Heilige Nova'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch den Zauber 'Heilige Nova'.\n\nLöst eine Explosion heiligen Lichts um den Zaubernden aus, die allen Gegnern im Umkreis von 10 Metern 13 Heiligschaden zufügt und bis zu 5 Verbündete in einem Umkreis von 10 Metern um 20 heilt.\n\nDie Heilung wird unter allen geheilten Zielen aufgeteilt. Diese Effekte erzeugen keine Bedrohung.\nVerkaufspreis:" }
entries[42402] = { ["name"] = "Glyphe 'Inneres Feuer'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die von Eurem Zauber 'Inneres Feuer' gewährte Rüstung um 50%.\nVerkaufspreis:" }
entries[42403] = { ["name"] = "Glyphe 'Tiefe Brunnen'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Anzahl der Aufladungen Eures Lichtbrunnens um 2.\nVerkaufspreis:" }
entries[42404] = { ["name"] = "Glyphe 'Massenbannung'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Massenbannung' wird mächtig genug, magische Effekte zu entfernen, die normalerweise nicht gebannt werden können.\nVerkaufspreis:" }
entries[42405] = { ["name"] = "Glyphe 'Psychisches Entsetzen'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Psychisches Entsetzen' um 10 Sek.\nVerkaufspreis:" }
entries[42406] = { ["name"] = "Glyphe 'Heiliges Feuer'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eurer Zauber 'Heiliges Feuer', 'Heilige Pein' und 'Machtwort: Trost' um 10 Meter.\nVerkaufspreis:" }
entries[42407] = { ["name"] = "Glyphe 'Geschwächte Seele'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Dauer des vom Zauber 'Machtwort: Schild' ausgelösten Effekts 'Geschwächte Seele' um 2 Sek.\nVerkaufspreis:" }
entries[42408] = { ["name"] = "Glyphe 'Machtwort: Schild'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWandelt 20% des Absorptionswertes Eures Zaubers 'Machtwort: Schild' in Heilung um.\nVerkaufspreis:" }
entries[42409] = { ["name"] = "Glyphe 'Geist der Erlösung'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht Eure Daseinsdauer als Geist der Erlösung um 10 Sek.\nVerkaufspreis:" }
entries[42410] = { ["name"] = "Glyphe 'Psychischer Schrei'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDie Ziele Eures Zaubers 'Psychischer Schrei' sowie des Zaubers 'Psychoterror' Eures Psychoschreckens erstarren nun vor Furcht, anstatt zu flüchten.\nVerkaufspreis:" }
entries[42411] = { ["name"] = "Glyphe 'Erneuerung'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer geheilte Wert jedes Ticks Eures Zaubers 'Erneuerung' wird um 33% erhöht, die Gesamtdauer des Effekts wird jedoch um 3 Sek. verringert.\nVerkaufspreis:" }
entries[42412] = { ["name"] = "Glyphe 'Geißelgefangennahme'", ["text"] = "Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Zauberzeit Eures Zaubers 'Untote fesseln' um 1.0 Sek.\nVerkaufspreis:" }
entries[42413] = { ["name"] = "Figur - Saphireule", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\n\nBlauer Sockel\nBlauer Sockel\nSockelbonus: + 4 Willenskraft\nBenötigt Stufe 75\nBenötigt Juwelierskunst\n(400)\nBenutzen: Stellt im Verlauf von 12 Sek. 2689 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:" }
