entries[42454] = { ["name"] = "Glyphe 'Feuersbrunst'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Feuersbrunst' setzt nicht mehr voraus, dass das Ziel von 'Feuerbrand' betroffen ist, um es zu verlangsamen.\nVerkaufspreis:" }
entries[42455] = { ["name"] = "Glyphe 'Lebensentzug'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber [ Feuerbrand : 'Feuerbrand' ] 'Verderbnis' heilt Euch um 0.5% Eurer Maximalgesundheit, wenn er [ Feuerbrand : regelmäßigen ] Schaden verursacht.\nVerkaufspreis:" }
entries[42456] = { ["name"] = "Glyphe 'Tiefgrüne Sphären'", ["text"] = "Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n[ Zerstörung : Aktive instabile Funken werden als grüne Sphären dargestellt, die um Euren Charakter wirbeln /\n\nGebrechen, Dämonologie\nEure Seelensplitter werden in grüne Sphären umgewandelt ]\nVerkaufspreis:" }
entries[42457] = { ["name"] = "Glyphe 'Alpträume'", ["text"] = "Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Teufelsross und Euer Schreckensross können übers Wasser hinwegreiten und hinterlassen eine Flammenspur.\nVerkaufspreis:" }
entries[42458] = { ["name"] = "Glyphe 'Furcht'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLässt das Ziel Eures Zaubers 'Furcht' vor Furcht erstarren, anstatt dass es flüchtet.\nVerkaufspreis:" }
entries[42459] = { ["name"] = "Glyphe 'Teufelswache'", ["text"] = "Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Teufelswache wird sich mit einer zufälligen Waffe der folgenden Arten ausrüsten, die sich in Euren Taschen befindet: Zweihandaxt, Zweihandschwert oder Stangenwaffe.\nVerkaufspreis:" }
entries[42460] = { ["name"] = "Glyphe 'Dämonisches Training'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerbessert die Spezialfähigkeiten Eures Dämons:\n\nVerringert die Zauberzeit des Zaubers 'Feuerblitz' Eures [ Grimoire der Überlegenheit : Teufelswichtels / Wichtels] um 50% und es werden 3 Blitze abgefeuert.\n\nErhöht die gesamte Rüstung Eures [ Grimoire der Überlegenheit : Leerenfürsten / Leerwandlers] um 10%.\n\nDie Fähigkeit [ Grimoire der Überlegenheit : 'Mesmerisieren' / 'Verführung'] [ Grimoire der Überlegenheit : Eurer Shivarra und Eures Erzinkubus / Eures Succubus und Inkubus] entfernt zusätzlich alle regelmäßigen Schadenseffekte vom Ziel.\n\nWenn Euer [ Grimoire der Überlegenheit : Beobachter / Teufelsjäger] die Fähigkeit [ Grimoire der Überlegenheit : 'Magie kopieren' / 'Magie verschlingen'] einsetzt, werdet Ihr um die gleiche Menge geheilt.\n\nErhöht die gesamte Gesundheit [ Grimoire der Überlegenheit : Eures Zornwächters / Eurer Teufelswache] um 20%.\nVerkaufspreis:" }
entries[42461] = { ["name"] = "Glyphe 'Lebenslinie'", ["text"] = "Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Lebenslinie' stellt sofort 15% der Gesundheit Eures Dämons wieder her, hat jedoch eine Abklingzeit von 10 Sek.\nVerkaufspreis:" }
entries[42462] = { ["name"] = "Glyphe 'Gesundheitsstein'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr gewinnt durch das Nutzen von Gesundheitssteinen 100% mehr Gesundheit, der Effekt wird jedoch zu einer regelmäßigen Heilung, die im Verlauf von 10 Sek. erfolgt.\nVerkaufspreis:" }
entries[42463] = { ["name"] = "Glyphe 'Subtilität'", ["text"] = "Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Seelensplitter werden außerhalb des Kampfes nicht mehr angezeigt.\nVerkaufspreis:" }
entries[42464] = { ["name"] = "Glyphe 'Fluch der Elemente'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Fluch der Elemente' trifft 2 zusätzliche Ziele in der Nähe.\nVerkaufspreis:" }
entries[42465] = { ["name"] = "Glyphe 'Wichtelschwarm'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBenötigt Dämonologie.\nLehrt Euch den Zauber 'Wichtelschwarm'.\n\nWichtelschwarm\nBeschwört 4 Wildwichtel aus dem Wirbelnden Nether, die das Ziel angreifen.\n\nDer passive Effekt von 'Wildwichtel' ist inaktiv, während der Zauber abklingt. Die Abklingzeit von 'Wichtelschwarm' wird von Tempo verringert. Erhöht außerdem die Abklingzeit von 'Wildwichtel' um 4 Sek.\nVerkaufspreis:" }
entries[42466] = { ["name"] = "Glyphe 'Verwüstung'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Zauber 'Verwüstung' erhält 3 zusätzliche Aufladungen, die Abklingzeit wird jedoch um 35 Sek. erhöht.\nVerkaufspreis:" }
entries[42467] = { ["name"] = "Glyphe 'Schattenblitz'", ["text"] = "Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nTeilt Euren Schattenblitz in drei kleinere Geschosse auf.\nVerkaufspreis:" }
entries[42468] = { ["name"] = "Verblichene Glyphe", ["text"] = "Klassen: Hexenmeister\n\"Die Magie dieser Glyphe ist verflogen, aber die Inschrift ist immer noch wunderschön anzusehen.\"\nVerkaufspreis:" }
entries[42469] = { ["name"] = "Verkohlte Glyphe", ["text"] = "\"Es sieht zwar aus, als wäre diese Glyphe entsetztlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[42470] = { ["name"] = "Glyphe 'Seelenstein'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nSpielercharaktere, die sich durch einen Seelenstein wiederbeleben, erstehen mit 100% Gesundheit auf.\nVerkaufspreis:" }
entries[42471] = { ["name"] = "Glyphe 'Aasschwarm'", ["text"] = "Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Aasschwarm' stößt Ziele nicht mehr zurück.\nVerkaufspreis:" }
entries[42472] = { ["name"] = "Glyphe 'Instabiles Gebrechen'", ["text"] = "Erhebliche Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Zauberzeit von 'Instabiles Gebrechen' um 25%.\nVerkaufspreis:" }
entries[42473] = { ["name"] = "Glyphe 'Fallender Meteor'", ["text"] = "Geringe Glyphe\nKlassen: Hexenmeister\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr aus dem Fallen heraus 'Dämonischer Sprung' wirkt, schlagt Ihr mit Wucht in den Boden ein, der Fallschaden bringt Euch jedoch nicht um.\nVerkaufspreis:" }
entries[42475] = { ["name"] = "Spezifikationen über Kolossangriffe", ["text"] = "Questgegenstand" }
entries[42476] = { ["name"] = "Spezifikationen über die Kolossverteidigung", ["text"] = "Questgegenstand" }
entries[42479] = { ["name"] = "Fangzahn eines astralen Worgs", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Innerhalb von 15 Metern um den gefallenen Worg beschwört der Fangzahn einen astralen Worg. Folgt dem Worg und beschützt ihn, während er die Spur des sturmgeschmiedeten Spitzels aufnimmt. (30 Sek. Abklingzeit)" }
entries[42480] = { ["name"] = "Banner der Schwarzen Klinge", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Den Leichnam eines toten Vrykul in der Gegend von Jotunheim anvisieren und aufspießen. Die Reichweite beträgt 15 Meter." }
entries[42481] = { ["name"] = "Zügel der Kriegsbärenmatriarchin", ["text"] = "Questgegenstand\nBenutzen: Beschwört eine Kriegsbärenmatriarchin in Brunnhildar. (15 Sek. Abklingzeit)" }
