entries[42732] = { ["name"] = "Immerfrostschneider", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Versucht, die Flanke eines Eisschlundbären aus einem toten Eisschlundbären in der Überwinterungshöhle herauszuschneiden. (10 Sek. Abklingzeit)" }
entries[42733] = { ["name"] = "Flanke eines Eisschlundbären", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Platziert die Flanke eines Eisschlundbären in Jorkuttars Krater im hinteren Teil der Überwinterungshöhle." }
entries[42734] = { ["name"] = "Verkohlte Glyphe", ["text"] = "\"Es sieht zwar aus, als wäre diese Glyphe entsetztlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[42735] = { ["name"] = "Glyphe 'Ungebundenes Mana'", ["text"] = "Geringe Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Manaedelstein stellt nun statt mit sofortiger Wirkung im Verlauf von 6 Sek. Mana wieder her.\nVerkaufspreis:" }
entries[42736] = { ["name"] = "Glyphe 'Arkane Explosion'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den Radius von 'Arkane Explosion' um 5 Meter.\nVerkaufspreis:" }
entries[42737] = { ["name"] = "Glyphe 'Blinzeln'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Teleportdistanz Eures Zaubers 'Blinzeln' um 8 Meter.\nVerkaufspreis:" }
entries[42738] = { ["name"] = "Glyphe 'Hervorrufung'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr stellt während der Dauer Eures Zaubers 'Hervorrufung' auch 60% Eurer Gesundheit wieder her.\n\nMit dem Talent 'Herbeirufung' gewinnt Ihr bei Abschluss des Kanalisierens von 'Hervorrufung' stattdessen 10% Eurer Gesundheit.\n\nMit dem Talent 'Rune der Kraft' regeneriert Ihr pro Sekunde 1% Eurer Gesundheit, während Ihr Euch innerhalb des Effektbereiches der Rune befindet.\nVerkaufspreis:" }
entries[42739] = { ["name"] = "Glyphe 'Einäschern'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den direkten Schaden, die Dauer des regelmäßigen Schadens und die Abklingzeit von 'Einäschern' um 100%.\nVerkaufspreis:" }
entries[42740] = { ["name"] = "Verkohlte Glyphe", ["text"] = "\"Es sieht zwar aus, als wäre diese Glyphe entsetztlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[42741] = { ["name"] = "Glyphe 'Frostnova'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Frostnova' um 5 Sek.\nVerkaufspreis:" }
entries[42742] = { ["name"] = "Verblichene Glyphe", ["text"] = "Klassen: Magier\n\"Die Magie dieser Glyphe ist verflogen, aber die Inschrift ist immer noch wunderschön anzusehen.\"\nVerkaufspreis:" }
entries[42743] = { ["name"] = "Glyphe 'Momentum'", ["text"] = "Geringe Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Blinzeln' teleportiert Euch in die Richtung, in die Ihr Euch bewegt, statt in Eure Blickrichtung.\nVerkaufspreis:" }
entries[42744] = { ["name"] = "Glyphe 'Eisblock'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn der Effekt 'Eisblock' abläuft, wird eine kostenlose Frostnova ausgelöst und Ihr seid 3 Sek. lang immun gegenüber allen Zaubern.\nVerkaufspreis:" }
entries[42745] = { ["name"] = "Glyphe 'Zersplitterndes Eis'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Eislanze' und Eure Eiszapfen treffen jetzt 1 zusätzliches Ziel und fügen ihm 50% Schaden zu.\nVerkaufspreis:" }
entries[42746] = { ["name"] = "Glyphe 'Kältekegel'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den von 'Kältekegel' verursachten Schaden um 200%.\nVerkaufspreis:" }
entries[42747] = { ["name"] = "Verkohlte Glyphe", ["text"] = "\"Es sieht zwar aus, als wäre diese Glyphe entsetztlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:" }
entries[42748] = { ["name"] = "Glyphe 'Schnelle Deplatzierung'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Blinzeln' hat jetzt 2 Aufladungen mit einer Aufladungszeit von 15 Sek., befreit Euch aber nicht mehr von Betäubungs- und Bewegungsunfähigkeitseffekten.\nVerkaufspreis:" }
entries[42749] = { ["name"] = "Glyphe 'Manaedelstein'", ["text"] = "Erhebliche Glyphe\nKlassen: Magier\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Manaedelstein herbeizaubern' erzeugt nun einen brillanten Manaedelstein, der über bis zu 10 Aufladungen verfügt.\nVerkaufspreis:" }
